<?php
session_start(); require_once 'config/conexao.php'; require_once 'config/auth.php'; exigir_cargo(['administrador','gerente','funcionario']); $nivel=$_SESSION['usuario']['nivel'];
if($_SERVER['REQUEST_METHOD']==='POST' && in_array($nivel,['administrador','gerente'],true)){
 $st=$_POST['status']??''; $id=(int)($_POST['id']??0);
 try {
  if(!in_array($st,['aberta','em_producao','concluida','cancelada'],true)) throw new Exception('Status inválido.');
  $pdo->beginTransaction(); $q=$pdo->prepare('SELECT * FROM vendas WHERE id=? FOR UPDATE');$q->execute([$id]);$v=$q->fetch();if(!$v)throw new Exception('Venda não encontrada.');
  if($v['status']==='cancelada' && $st!=='cancelada') throw new Exception('Uma venda cancelada não pode ser reaberta.');
  if($v['status']!=='cancelada' && $st==='cancelada' && $v['tipo']==='direta'){
   $q=$pdo->prepare('SELECT vi.*,p.nome FROM venda_itens vi JOIN produtos p ON p.id=vi.produto_id WHERE vi.venda_id=?');$q->execute([$id]);
   foreach($q->fetchAll() as $item){$pdo->prepare('UPDATE produtos SET quantidade=quantidade+? WHERE id=?')->execute([$item['quantidade'],$item['produto_id']]);$pdo->prepare("INSERT INTO estoque_movimentacoes(produto_id,usuario_id,tipo,quantidade,observacao) VALUES(?,?,'entrada',?,?)")->execute([$item['produto_id'],$_SESSION['usuario']['id'],$item['quantidade'],'Estorno da venda cancelada #'.$id]);}
  }
  $pdo->prepare('UPDATE vendas SET status=? WHERE id=?')->execute([$st,$id]);$pdo->commit();flash('Status da venda atualizado.');
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash($e->getMessage());}
 header('Location: vendas.php');exit;
}
$sql="SELECT v.*,u.nome AS vendedor,p.servico AS pedido_servico FROM vendas v JOIN usuarios u ON u.id=v.usuario_id LEFT JOIN pedidos p ON p.id=v.pedido_id";if($nivel==='funcionario'){$sql.=' WHERE v.usuario_id='.(int)$_SESSION['usuario']['id'];}$sql.=' ORDER BY COALESCE(v.data_venda,DATE(v.criado_em)) DESC,v.id DESC';$vendas=$pdo->query($sql)->fetchAll();
$itensQ=$pdo->prepare('SELECT vi.*,p.nome,p.unidade FROM venda_itens vi JOIN produtos p ON p.id=vi.produto_id WHERE vi.venda_id=?');
?>
<!DOCTYPE html><html lang="pt-br"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Vendas</title><link rel="stylesheet" href="style.css"></head><body><main class="app"><header class="topbar"><h2>Vendas e faturamentos</h2><a class="link-sair" href="painel.php">← Painel</a></header><section class="content"><?php mostrar_flash();?><a class="button-link" href="nova_venda.php">+ Nova venda / faturamento</a><div class="table-wrap"><table><thead><tr><th>#</th><th>Tipo</th><th>Cliente / pedido</th><th>Itens</th><th>Responsável</th><th>Total</th><th>Status</th><th>Data</th><?php if($nivel!=='funcionario'):?><th>Atualizar</th><?php endif;?></tr></thead><tbody><?php foreach($vendas as $v):?><tr><td>#<?=$v['id']?></td><td><?=$v['tipo']==='servico'?'Serviço gráfico':'Venda direta'?></td><td><?=h($v['cliente']?:'—')?><?php if($v['pedido_id']):?><br><small>Pedido #<?=$v['pedido_id']?> · <?=h($v['pedido_servico'])?></small><?php endif;?></td><td><?php if($v['tipo']==='servico'):?>Faturamento de serviço<?php else:$itensQ->execute([$v['id']]);foreach($itensQ->fetchAll() as $it):?><div><?=h($it['nome'])?> — <?=h($it['quantidade'])?> <?=h($it['unidade'])?> × R$ <?=number_format((float)$it['preco_unitario'],2,',','.')?></div><?php endforeach;endif;?></td><td><?=h($v['vendedor'])?></td><td>R$ <?=number_format((float)$v['total'],2,',','.')?></td><td><?=h($v['status'])?></td><td><?=date('d/m/Y',strtotime($v['data_venda']?:$v['criado_em']))?></td><?php if($nivel!=='funcionario'):?><td><?php if($v['status']!=='cancelada'):?><form method="post" class="inline"><input type="hidden" name="id" value="<?=$v['id']?>"><select name="status"><option value="aberta" <?=$v['status']==='aberta'?'selected':''?>>Aberta</option><option value="em_producao" <?=$v['status']==='em_producao'?'selected':''?>>Em produção</option><option value="concluida" <?=$v['status']==='concluida'?'selected':''?>>Concluída</option><option value="cancelada">Cancelar</option></select><button class="mini">Salvar</button></form><?php else:?>Cancelada<?php endif;?></td><?php endif;?></tr><?php endforeach;?><?php if(!$vendas):?><tr><td colspan="9">Nenhuma venda registrada no período.</td></tr><?php endif;?></tbody></table></div></section></main></body></html>
